"""Deterministic synthetic Windows Security telemetry with labelled attack and false-positive scenarios.

Safety and privacy
------------------
* Everything is generated by code from a seed. There is no real person, host, address or credential in the data.
* External sources use RFC 5737 documentation ranges (192.0.2.0/24, 198.51.100.0/24, 203.0.113.0/24) and, for the
  independent profile, RFC 6598 shared space (100.64.0.0/10). Internal sources use RFC 1918. Domain: corp.example.

Determinism
-----------
All randomness comes from ``random.Random(seed)``; scenario builders are called in a fixed order and the final
event list is sorted by (timestamp, insertion order). The same (profile, seed) always yields byte-identical output.

Profiles
--------
``guided``       Dataset A for the guided lab (8 h, Monday 2026-03-02).
``independent``  Dataset B for the independent lab (10 h, Monday 2026-03-09): sources in many /24 networks, a
                 brute-force-then-success case, a lock-out loop and a second change-window scanner-like source.

Scenario kinds: ATTACK (must be detected) and BENIGN (activity that naive rules misread as an attack).
"""
from __future__ import annotations

import datetime as dt
import random
from dataclasses import dataclass, field

from .events import UTC, fmt_ts

FIRST = ["alex", "bea", "carl", "dana", "eli", "fay", "gus", "hana", "ian", "jo", "kai", "lena", "max", "nia", "omar",
         "pia", "quin", "rae", "sam", "tia"]
LAST = ["adams", "baker", "chen", "diaz", "evans", "ford", "gupta", "hill", "ito", "jones", "khan", "lopez", "moss",
        "nash", "ortiz", "park", "quill", "reed", "shaw", "tran"]

ST_BAD_CREDS = "0xC000006D"      # bad user name or authentication information
SUB_BAD_PASSWORD = "0xC000006A"  # bad password (user exists)
SUB_BAD_USER = "0xC0000064"      # user name does not exist
ST_LOCKED_OUT = "0xC0000234"     # account locked out
DOMC = "DC01.corp.example"
RDS = "RDS01.corp.example"
FS = "FS01.corp.example"


@dataclass
class Dataset:
    profile: str
    seed: int
    events: list[dict]
    labels: dict[str, str]
    scenarios: list[dict]
    context: dict


@dataclass
class _Builder:
    rng: random.Random
    day: dt.datetime
    raw: list[tuple[dt.datetime, int, dict, str]] = field(default_factory=list)
    counter: int = 0

    def at(self, hh: int, mm: int = 0, ss: int = 0) -> dt.datetime:
        return self.day.replace(hour=hh, minute=mm, second=ss)

    def add(self, ts: dt.datetime, scenario: str, **fields) -> None:
        self.counter += 1
        self.raw.append((ts, self.counter, fields, scenario))

    # -- event shapes --------------------------------------------------------------------------------------------
    def fail(self, ts, scenario, user, ip, ltype=3, computer=DOMC, workstation="-", sub=SUB_BAD_PASSWORD, status=ST_BAD_CREDS):
        self.add(ts, scenario, EventID=4625, Computer=computer, TargetUserName=user, TargetDomainName="CORP",
                 LogonType=ltype, IpAddress=ip, WorkstationName=workstation, Status=status, SubStatus=sub,
                 AuthenticationPackageName="NTLM")

    def ok(self, ts, scenario, user, ip, ltype=3, computer=DOMC, workstation="-", pkg="Kerberos"):
        self.add(ts, scenario, EventID=4624, Computer=computer, TargetUserName=user, TargetDomainName="CORP",
                 LogonType=ltype, IpAddress=ip, WorkstationName=workstation, AuthenticationPackageName=pkg)


def _users(rng: random.Random, n: int, fixed: list[str]) -> list[str]:
    pool = [f"{f[0]}.{l}" for f in FIRST for l in LAST]
    rng.shuffle(pool)
    names = list(fixed)
    for p in pool:
        if len(names) >= n:
            break
        if p not in names:
            names.append(p)
    return sorted(names)


def _ip_of(users: list[str], vpn_users: set[str], user: str) -> str:
    if user in vpn_users:
        return "10.0.9.5"
    return f"10.0.20.{10 + users.index(user)}"


# -------------------------------------------------------------------------------------------- benign behaviour


def benign_logons(b: _Builder, users, vpn_users, start_h=8, end_h=16, scenario="N0"):
    for u in users:
        for _ in range(b.rng.randint(2, 5)):
            ts = b.at(start_h) + dt.timedelta(seconds=b.rng.randint(0, (end_h - start_h) * 3600 - 1))
            lt = b.rng.choice([2, 2, 3, 10])
            comp = RDS if lt == 10 else DOMC
            b.ok(ts, scenario, u, _ip_of(users, vpn_users, u), ltype=lt, computer=comp, workstation=f"WKS-{users.index(u):03d}")


def typo_failures(b: _Builder, users, vpn_users, n, start_h=8, end_h=16, scenario="N0"):
    """A user mistypes a password and succeeds 15-60 s later (the benign shape that ratio/success logic exploits)."""
    for _ in range(n):
        u = b.rng.choice(users)
        ts = b.at(start_h) + dt.timedelta(seconds=b.rng.randint(0, (end_h - start_h) * 3600 - 120))
        ip = _ip_of(users, vpn_users, u)
        b.fail(ts, scenario, u, ip, ltype=b.rng.choice([2, 3]), workstation=f"WKS-{users.index(u):03d}")
        b.ok(ts + dt.timedelta(seconds=b.rng.randint(15, 60)), scenario, u, ip, ltype=3, workstation=f"WKS-{users.index(u):03d}")


def vpn_rush(b: _Builder, users, accounts, start, window_s, scenario):
    """Many users behind one VPN NAT address mistype within minutes; each succeeds shortly after."""
    for u in accounts:
        ts = start + dt.timedelta(seconds=b.rng.randint(0, window_s))
        b.fail(ts, scenario, u, "10.0.9.5", ltype=3, workstation="VPNGW01")
        b.ok(ts + dt.timedelta(seconds=b.rng.randint(20, 70)), scenario, u, "10.0.9.5", ltype=3, workstation="VPNGW01")


def service_loop(b: _Builder, account, ip, host, start, end, interval_s, scenario, status=ST_BAD_CREDS, sub=SUB_BAD_PASSWORD):
    """A service account with a stale credential retries forever."""
    ts = start
    while ts < end:
        b.fail(ts + dt.timedelta(seconds=b.rng.randint(0, 2)), scenario, account, ip, ltype=3, computer=FS, workstation=host, sub=sub, status=status)
        ts += dt.timedelta(seconds=interval_s)


def scanner_sweep(b: _Builder, ip, host, accounts, start, spacing_s, scenario):
    ts = start
    for u in accounts:
        b.fail(ts, scenario, u, ip, ltype=3, workstation=host)
        ts += dt.timedelta(seconds=spacing_s + b.rng.randint(0, 6))


# -------------------------------------------------------------------------------------------- attacks


def single_account_bruteforce(b: _Builder, ip, account, start, attempts, spacing_s, scenario, success_after_s=None, computer=RDS):
    ts = start
    for _ in range(attempts):
        b.fail(ts, scenario, account, ip, ltype=3, computer=computer)
        ts += dt.timedelta(seconds=spacing_s + b.rng.randint(0, 1))
    if success_after_s is not None:
        b.ok(ts + dt.timedelta(seconds=success_after_s), scenario, account, ip, ltype=10, computer=computer, workstation="ATTACKER-WS", pkg="NTLM")


def single_source_spray(b: _Builder, ip, accounts, start, rounds, round_gap_min, spacing_s, scenario, invalid_names=0,
                        success_for=None, success_delay_s=150, computer=DOMC):
    for r in range(rounds):
        ts = start + dt.timedelta(minutes=r * round_gap_min)
        for u in accounts:
            b.fail(ts, scenario, u, ip, ltype=3, computer=computer)
            ts += dt.timedelta(seconds=spacing_s + b.rng.randint(0, 1))
        if r == 0:
            for i in range(invalid_names):
                b.fail(ts, scenario, f"svc-{FIRST[i]}{i}", ip, ltype=3, computer=computer, sub=SUB_BAD_USER)
                ts += dt.timedelta(seconds=spacing_s)
    if success_for:
        end = start + dt.timedelta(minutes=(rounds - 1) * round_gap_min, seconds=spacing_s * len(accounts) + success_delay_s)
        b.ok(end, scenario, success_for, ip, ltype=10, computer=RDS, workstation="ATTACKER-WS", pkg="NTLM")
        b.ok(end + dt.timedelta(minutes=4), scenario, success_for, ip, ltype=10, computer=RDS, workstation="ATTACKER-WS", pkg="NTLM")
        b.ok(end + dt.timedelta(minutes=13), scenario, success_for, ip, ltype=3, computer=FS, workstation="ATTACKER-WS", pkg="NTLM")


def distributed_spray(b: _Builder, ips, accounts, start, minutes, per_account, scenario, computer=DOMC):
    """Each account is tried per_account times, each time from a different source, spaced out over `minutes`."""
    for u in accounts:
        chosen = b.rng.sample(ips, per_account)
        slots = sorted(b.rng.sample(range(minutes * 60), per_account))
        for ip, off in zip(chosen, slots):
            b.fail(start + dt.timedelta(seconds=off), scenario, u, ip, ltype=3, computer=computer)


# -------------------------------------------------------------------------------------------- profiles


def _context(profile: str, day: dt.datetime, users, vpn_users, extra_assets, change_calendar, service_accounts) -> dict:
    assets = [
        {"ip": "10.0.9.5", "hostname": "VPNGW01", "role": "vpn_nat", "owner": "netops",
         "note": "All VPN users share this address (NAT)."},
        {"ip": "10.0.2.15", "hostname": "BACKUP01", "role": "backup_server", "owner": "it-ops"},
    ] + extra_assets
    return {
        "profile": profile,
        "domain": "CORP",
        "timezone": "UTC",
        "assets": sorted(assets, key=lambda a: a["ip"]),
        "networks": [
            {"cidr": "10.0.20.0/24", "role": "workstation_lan"},
            {"cidr": "10.0.0.0/8", "role": "internal"},
        ],
        "change_calendar": change_calendar,
        "service_accounts": service_accounts,
        "users": [{"name": u, "vpn_user": u in vpn_users} for u in users],
        "date": day.strftime("%Y-%m-%d"),
    }


def _finalize(b: _Builder, profile: str, seed: int, scenarios: list[dict], context: dict) -> Dataset:
    b.raw.sort(key=lambda t: (t[0], t[1]))
    events, labels = [], {}
    for i, (ts, _n, fields, scenario) in enumerate(b.raw, 1):
        eid = f"evt-{i:06d}"
        row = {"event_id": eid, "@timestamp": fmt_ts(ts), "Channel": "Security"}
        row.update(fields)
        events.append(row)
        labels[eid] = scenario
    # scenario windows are derived from the events, so they can never disagree with the data
    by_sc: dict[str, list[dict]] = {}
    for ev in events:
        by_sc.setdefault(labels[ev["event_id"]], []).append(ev)
    for sc in scenarios:
        exp = TRIAGE_EXPECTATIONS.get(profile, {}).get(sc["id"])
        if exp:
            sc["triage_expectation"] = exp
        evs = by_sc.get(sc["id"], [])
        sc["event_count"] = len(evs)
        sc["first_event"] = evs[0]["@timestamp"] if evs else None
        sc["last_event"] = evs[-1]["@timestamp"] if evs else None
    return Dataset(profile, seed, events, labels, scenarios, context)


def _guided(seed: int) -> Dataset:
    rng = random.Random(seed)
    day = dt.datetime(2026, 3, 2, tzinfo=UTC)
    b = _Builder(rng, day)
    users = _users(rng, 60, ["j.doe", "m.lee", "svc-scanner"])
    humans = [u for u in users if not u.startswith("svc-")]
    vpn_users = set(rng.sample(humans, 20)) - {"j.doe", "m.lee"}
    benign_logons(b, humans, vpn_users)
    typo_failures(b, humans, vpn_users, 45)
    rush_users = rng.sample(sorted(vpn_users), 14)
    vpn_rush(b, humans, rush_users, b.at(8, 55), 540, "F4")
    service_loop(b, "svc-backup", "10.0.2.15", "BACKUP01", b.at(8, 0, 7), b.at(12, 0), 30, "F1")
    scan_targets = rng.sample(humans, 35)
    b.ok(b.at(10, 1, 50), "F2", "svc-scanner", "10.0.5.20", ltype=3, workstation="VULNSCAN01")
    scanner_sweep(b, "10.0.5.20", "VULNSCAN01", scan_targets, b.at(10, 2), 40, "F2")
    # attacks
    single_account_bruteforce(b, "198.51.100.23", "j.doe", b.at(12, 20), 90, 3, "S1")
    spray_targets = rng.sample([u for u in humans if u not in ("m.lee",)], 40)
    single_source_spray(b, "203.0.113.77", spray_targets, b.at(13, 0), 2, 15, 8, "S2", invalid_names=8)
    s3_accounts = rng.sample(humans, 25)
    distributed_spray(b, [f"192.0.2.{n}" for n in range(10, 16)], s3_accounts, b.at(10, 30), 180, 5, "S3")
    s4_targets = ["m.lee"] + rng.sample([u for u in humans if u != "m.lee"], 29)
    single_source_spray(b, "203.0.113.88", s4_targets, b.at(14, 0), 1, 0, 10, "S4", success_for="m.lee", success_delay_s=140)
    scanner_sweep(b, "10.0.5.20", "VULNSCAN01", rng.sample(humans, 30), b.at(14, 10), 20, "S6")

    scenarios = [
        {"id": "N0", "kind": "BENIGN", "name": "Ordinary logons and occasional typos", "mitre": None, "fp_source": False},
        {"id": "F1", "kind": "BENIGN", "name": "Backup service account retrying a stale password every 30 s", "mitre": None, "fp_source": True},
        {"id": "F2", "kind": "BENIGN", "name": "Authorised authenticated vulnerability scan (change CHG-1042, 10:00-10:30)", "mitre": None, "fp_source": True},
        {"id": "F4", "kind": "BENIGN", "name": "Morning VPN rush: many users behind one NAT address mistype once", "mitre": None, "fp_source": True},
        {"id": "S1", "kind": "ATTACK", "name": "Password guessing against one account from one external address", "mitre": "T1110.001", "fp_source": False},
        {"id": "S2", "kind": "ATTACK", "name": "Password spraying from one external address (2 rounds, includes invalid user names)", "mitre": "T1110.003", "fp_source": False},
        {"id": "S3", "kind": "ATTACK", "name": "Distributed low-and-slow spraying from six addresses in one /24", "mitre": "T1110.003", "fp_source": False},
        {"id": "S4", "kind": "ATTACK", "name": "Password spray followed by a successful remote logon (compromise)", "mitre": "T1110.003", "fp_source": False},
        {"id": "S6", "kind": "ATTACK", "name": "Scanner address used for spraying outside its change window", "mitre": "T1110.003", "fp_source": False},
    ]
    extra = [{"ip": "10.0.5.20", "hostname": "VULNSCAN01", "role": "vulnerability_scanner", "owner": "secops"}]
    cal = [{"ticket": "CHG-1042", "description": "Authenticated vulnerability scan", "asset_ip": "10.0.5.20",
            "start": "2026-03-02T10:00:00Z", "end": "2026-03-02T10:30:00Z", "owner": "secops"}]
    svc = [{"name": "svc-backup", "owner": "it-ops", "expected_sources": ["10.0.2.15"]},
           {"name": "svc-scanner", "owner": "secops", "expected_sources": ["10.0.5.20"]}]
    ctx = _context("guided", day, users, vpn_users, extra, cal, svc)
    return _finalize(b, "guided", seed, scenarios, ctx)


def _independent(seed: int) -> Dataset:
    rng = random.Random(seed)
    day = dt.datetime(2026, 3, 9, tzinfo=UTC)
    b = _Builder(rng, day)
    users = _users(rng, 70, ["adm-ops", "r.khan", "svc-report", "svc-helpdesk"])
    humans = [u for u in users if not u.startswith("svc-") and u != "adm-ops"]
    vpn_users = set(rng.sample(humans, 26)) - {"r.khan"}
    benign_logons(b, humans + ["adm-ops"], vpn_users, 8, 18)
    typo_failures(b, humans, vpn_users, 55, 8, 18)
    rush_users = rng.sample(sorted(vpn_users), 18)
    vpn_rush(b, humans, rush_users, b.at(8, 50), 540, "F4")
    service_loop(b, "svc-report", "10.0.3.44", "REPORT01", b.at(9, 0), b.at(11, 0), 20, "F1", status=ST_LOCKED_OUT, sub="0x0")
    # helpdesk validates 12 accounts during CHG-2210 (10:00-10:30): single source, many distinct accounts
    b.ok(b.at(10, 5), "F3", "svc-helpdesk", "10.0.7.30", ltype=3, workstation="HELPDESK02")
    scanner_sweep(b, "10.0.7.30", "HELPDESK02", rng.sample(humans, 12), b.at(10, 10), 40, "F3")
    # attacks
    ext = [f"100.64.{n}.{rng.randint(10, 240)}" for n in range(1, 11)]
    targets = rng.sample(humans, 25)
    for hour in range(11, 17):
        for i, u in enumerate(targets):
            ip = ext[(i + 3 * (hour - 11)) % len(ext)]  # deterministic rotation: every account sees 6 different sources
            b.fail(b.at(hour) + dt.timedelta(seconds=rng.randint(0, 3500)), "S1", u, ip, ltype=3)
    single_account_bruteforce(b, "192.0.2.201", "adm-ops", b.at(15, 10), 45, 6, "S2", success_after_s=75)
    scenarios = [
        {"id": "N0", "kind": "BENIGN", "name": "Ordinary logons and occasional typos", "mitre": None, "fp_source": False},
        {"id": "F1", "kind": "BENIGN", "name": "Reporting service account stuck in a lock-out loop (0xC0000234 every 20 s)", "mitre": None, "fp_source": True},
        {"id": "F3", "kind": "BENIGN", "name": "Help-desk workstation validating 12 accounts inside change CHG-2210 (10:00-10:30)", "mitre": None, "fp_source": True},
        {"id": "F4", "kind": "BENIGN", "name": "Morning VPN rush behind one NAT address (18 users)", "mitre": None, "fp_source": True},
        {"id": "S1", "kind": "ATTACK", "name": "Very slow distributed spray: 25 accounts, 10 sources in 10 different /24 networks, one attempt per account per hour", "mitre": "T1110.003", "fp_source": False},
        {"id": "S2", "kind": "ATTACK", "name": "Brute force against a privileged account followed by a successful RDP logon", "mitre": "T1110.001", "fp_source": False},
    ]
    extra = [{"ip": "10.0.7.30", "hostname": "HELPDESK02", "role": "helpdesk_workstation", "owner": "it-support"},
             {"ip": "10.0.3.44", "hostname": "REPORT01", "role": "reporting_server", "owner": "bi-team"}]
    cal = [{"ticket": "CHG-2210", "description": "Help-desk credential validation after migration", "asset_ip": "10.0.7.30",
            "start": "2026-03-09T10:00:00Z", "end": "2026-03-09T10:30:00Z", "owner": "it-support"}]
    svc = [{"name": "svc-report", "owner": "bi-team", "expected_sources": ["10.0.3.44"]},
           {"name": "svc-helpdesk", "owner": "it-support", "expected_sources": ["10.0.7.30"]}]
    ctx = _context("independent", day, users, vpn_users, extra, cal, svc)
    return _finalize(b, "independent", seed, scenarios, ctx)


# Structural expectations used by the triage checker (what a defensible triage decision looks like per scenario).
TRIAGE_EXPECTATIONS = {
    "guided": {
        "S1": {"classification": ["TRUE_POSITIVE_ATTACK"], "disposition": ["BLOCK_SOURCE", "ESCALATE_IR"], "mitre": ["T1110.001"]},
        "S4": {"classification": ["TRUE_POSITIVE_COMPROMISE"], "disposition": ["ESCALATE_IR", "CONTAIN_ACCOUNT_RESET"],
               "mitre": ["T1110.003"], "must_cite_success_event": True, "must_check": ["success_events"]},
        "S6": {"classification": ["TRUE_POSITIVE_ATTACK", "SUSPICIOUS_NEEDS_MORE_DATA"], "disposition": ["ESCALATE_IR"],
               "mitre": ["T1110.003"], "must_check": ["change_calendar", "asset_inventory"]},
        "F1": {"classification": ["FALSE_POSITIVE_MISCONFIGURATION"], "disposition": ["CLOSE_WITH_TUNING"], "must_have_root_cause_fix": True,
               "tuning_must_match": ["TargetUserName", "IpAddress"], "must_check": ["asset_inventory"]},
        "F2": {"classification": ["FALSE_POSITIVE_BENIGN_ACTIVITY"], "disposition": ["CLOSE_WITH_TUNING"], "must_check": ["change_calendar"],
               "tuning_must_match": ["IpAddress"], "tuning_ticket": "CHG-1042", "tuning_window": ["2026-03-02T10:00:00Z", "2026-03-02T10:30:00Z"]},
    },
    "independent": {
        "S1": {"classification": ["TRUE_POSITIVE_ATTACK"], "disposition": ["BLOCK_SOURCE", "ESCALATE_IR"], "mitre": ["T1110.003"]},
        "S2": {"classification": ["TRUE_POSITIVE_COMPROMISE"], "disposition": ["ESCALATE_IR", "CONTAIN_ACCOUNT_RESET"],
               "mitre": ["T1110.001"], "must_cite_success_event": True, "must_check": ["success_events"]},
        "F1": {"classification": ["FALSE_POSITIVE_MISCONFIGURATION"], "disposition": ["CLOSE_WITH_TUNING"], "must_have_root_cause_fix": True,
               "tuning_must_match": ["TargetUserName", "IpAddress"], "must_check": ["asset_inventory"]},
        "F3": {"classification": ["FALSE_POSITIVE_BENIGN_ACTIVITY"], "disposition": ["CLOSE_WITH_TUNING"], "must_check": ["change_calendar"],
               "tuning_must_match": ["IpAddress"], "tuning_ticket": "CHG-2210", "tuning_window": ["2026-03-09T10:00:00Z", "2026-03-09T10:30:00Z"]},
    },
}

DEFAULT_SEEDS = {"guided": 20260302, "independent": 20260309}


def generate(profile: str, seed: int | None = None) -> Dataset:
    if profile not in DEFAULT_SEEDS:
        raise ValueError(f"unknown profile {profile!r}; choose from {sorted(DEFAULT_SEEDS)}")
    seed = DEFAULT_SEEDS[profile] if seed is None else seed
    return _guided(seed) if profile == "guided" else _independent(seed)
